async def send_lock_command(lock_id: str, body: LockCommand) -> Dict[str, Any]:
    """Lock/unlock a smart lock."""
    if alarm_com_client is None:
        raise HTTPException(status_code=500, detail="Alarm.com client not initialized")

    cmd_map = {"lock": alarm_com_client.lock, "unlock": alarm_com_client.unlock}
    handler = cmd_map.get(body.command)
    if not handler:
        raise HTTPException(status_code=400, detail=f"Unknown command: {body.command}")

    try:
        result = await handler(lock_id)
        return result
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

async def send_device_command(endpoint_id: str, cmd: DeviceCommand) -> Dict[str, Any]:
    """Send a command to an Alexa device"""
    if alexa_service is None:
        raise HTTPException(status_code=500, detail="Alexa service not initialized")

    # Unlock commands require PIN confirmation
    if cmd.command == "unlock" and not cmd.pin:
        raise HTTPException(status_code=400, detail="PIN required for unlock commands")

    try:
        result = alexa_service.send_command(endpoint_id, cmd.command, cmd.params)
        return {
            "success": True,
            "command": cmd.command,
            "endpoint_id": endpoint_id,
            "result": result,
        }
    except ValueError as e:
        raise HTTPException(status_code=400, detail=str(e))
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Command failed: {e}")

async def control_smart_home_device(entity_id: str, cmd: SmartHomeCommand) -> Dict[str, Any]:
    """Control a smart home device (plug/light) via cookie-based API."""
    if alexa_client is None:
        raise HTTPException(status_code=500, detail="Alexa client not initialized")
    if not alexa_client.has_cookies():
        raise HTTPException(status_code=400, detail="Alexa cookies not configured")

    try:
        result = alexa_client.smart_home_control(entity_id, cmd.action, cmd.params)
        return {
            "success": result.get("success", False),
            "entity_id": entity_id,
            "action": cmd.action,
            "responses": result.get("responses", []),
            "errors": result.get("errors", []),
        }
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Command failed: {e}")

const optimizeNetwork = async () => {
  setOptimizeLoading(true);
  try {
    const response = await fetch(buildUrl('/deco/optimize-network'), {
      method: 'POST',
    });
    if (response.ok) {
      const data = await response.json();
      if (data.success) {
        showBanner(data.message, 'success');
      } else {
        showBanner(`Optimization failed: ${data.message}`, 'error');
      }
    } else {
      showBanner('Failed to start optimization. Deco may not be reachable.', 'error');
    }
  } catch (error) {
    console.error('Failed to optimize network:', error);
    showBanner('Failed to optimize network. Check Deco connectivity.', 'error');
  } finally {
    setOptimizeLoading(false);
  }
};

const toggleClientMesh = async (macAddress, currentMeshValue) => {
  const newValue = !currentMeshValue;
  const mac = macAddress.toLowerCase();
  // Optimistic update — flip immediately, revert if Deco rejects
  setClientNodeMap(prev =>
    prev[mac] ? { ...prev, [mac]: { ...prev[mac], client_mesh: newValue } } : prev
  );
  try {
    const response = await fetch(buildUrl('/deco/client-mesh'), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ mac_address: macAddress, mesh_enabled: newValue }),
    });
    if (response.ok) {
      const data = await response.json();
      if (!data.success) {
        // Deco rejected — revert
        setClientNodeMap(prev =>
          prev[mac] ? { ...prev, [mac]: { ...prev[mac], client_mesh: currentMeshValue } } : prev
        );
        console.warn('Mesh toggle returned error_code:', data.error_code);
      }
    } else {
      setClientNodeMap(prev =>
        prev[mac] ? { ...prev, [mac]: { ...prev[mac], client_mesh: currentMeshValue } } : prev
      );
    }
  } catch (error) {
    setClientNodeMap(prev =>
      prev[mac] ? { ...prev, [mac]: { ...prev[mac], client_mesh: currentMeshValue } } : prev
    );
    console.error('Failed to toggle client mesh:', error);
  }
};

const setPreferredDecoNode = async (deviceId, nodeMAC) => {
  // Capture old value for rollback on failure
  const oldDevice = devices.find(d => d.device_id === deviceId);
  const oldValue = oldDevice ? oldDevice.preferred_deco_node : undefined;
  // Optimistic update — flip immediately, server confirms in background
  setDevices(prev => prev.map(d =>
    d.device_id === deviceId ? { ...d, preferred_deco_node: nodeMAC } : d
  ));
  try {
    const res = await fetch(buildUrl(`/devices/${deviceId}`), {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ preferred_deco_node: nodeMAC }),
    });
    if (res.ok) {
      const updated = await res.json();
      setDevices(prev => prev.map(d =>
        d.device_id === updated.device_id ? updated : d
      ));
    } else {
      // Rollback on non-ok response
      setDevices(prev => prev.map(d =>
        d.device_id === deviceId ? { ...d, preferred_deco_node: oldValue } : d
      ));
    }
  } catch (e) {
    // Rollback on error
    setDevices(prev => prev.map(d =>
      d.device_id === deviceId ? { ...d, preferred_deco_node: oldValue } : d
    ));
    console.error('Failed to set preferred Deco node:', e);
  }
};

