    if (data.success) {
      setOtpRequired(false);
      setOtpCode('');
      await fetchStatus();
      await fetchDevices();
    } else {
      setError(data.detail || 'OTP failed');
    }
  } catch (err) {
    setError(err.message);
  } finally {
    setLoginLoading(false);
  }
};

