useEffect(() => {
  const fetchFallbackClients = async () => {
    try {
      const response = await fetch(buildUrl('/devices'));
      if (!response.ok) return;
      const data = await response.json();
      // Show all devices, sorted: online first, then by friendly_name presence, then by last_seen
      const allDevices = (data.devices || []).sort((a, b) => {
        if (a.status !== b.status) return a.status === 'online' ? -1 : 1;
        const aName = a.friendly_name || '';
        const bName = b.friendly_name || '';
        if (!!aName !== !!bName) return aName ? -1 : 1;
        return (b.last_seen || '').localeCompare(a.last_seen || '');
      });
      setFallbackClients(allDevices);
    } catch (err) {
      console.error('Failed to fetch fallback client list:', err);
    }
  };

  fetchFallbackClients();
}, [nodes, loading, error]);

const fetchData = useCallback(async (forceRefresh = false) => {
  try {
    // First get device list to find the device ID
    const statusResp = await fetch(buildUrl('/hiboost/status'));
    if (!statusResp.ok) throw new Error('HiBoost not connected');
    const status = await statusResp.json();
    if (!status.connected || !status.devices?.length) {
      setError('No HiBoost devices found. Check Settings.');
      setLoading(false);
      return;
    }

    const deviceId = status.devices[0].id;
    const endpoint = forceRefresh
      ? `/hiboost/devices/${deviceId}/refresh`
      : `/hiboost/devices/${deviceId}/rf-params`;
    const method = forceRefresh ? 'POST' : 'GET';

    const resp = await fetch(buildUrl(endpoint), { method });
    if (!resp.ok) throw new Error(`Failed to fetch RF params: ${resp.status}`);
    const data = await resp.json();
    setRfData(data);
    setError(null);
  } catch (err) {
    setError(err.message);
  } finally {
    setLoading(false);
    setRefreshing(false);
  }
}, []);

