@staticmethod
def _decode_alias(alias: str) -> str:
    """Decode base64-encoded Deco device alias, return as-is if not base64."""
    if not alias:
        return alias
    try:
        decoded = base64.b64decode(alias).decode("utf-8")
        if decoded.isprintable():
            return decoded
    except Exception as e:
        logger.debug(f"Base64 alias decode failed: {e}")
    return alias

def _ec_mul(k: int, x: int, y: int) -> Tuple[int, int]:
    """Scalar multiplication on P-256 using double-and-add."""
    rx, ry = None, None
    qx, qy = x, y
    while k > 0:
        if k & 1:
            if rx is None:
                rx, ry = qx, qy
            else:
                rx, ry = _ec_add(rx, ry, qx, qy)
        qx, qy = _ec_add(qx, qy, qx, qy)
        k >>= 1
    return rx, ry

