    ]

    # Deco nodes as switches (on = online monitoring)
    try:
        if deco_client and deco_client.is_authenticated():
            nodes = deco_client.get_device_list()
        elif deco_client:
            deco_client.authenticate()
            nodes = deco_client.get_device_list()
        else:
            nodes = []
    except Exception as e:
